// Kira Data pages. /<locale>/data/ lists the 15 markets; /<locale>/data/<country> (→ _view.html) shows one market.
// Numbers come from /api/econ, which serves only sources whose licence allows showing them (data_sources.public).
// The lead sentence is a fixed template filled with the latest values; no text is generated by a model.
(async function () {
  const root = document.getElementById('ed-root');
  if (!root) return;
  const parts = location.pathname.split('/').filter(Boolean);
  const locale = ['en', 'ja', 'ko', 'zh'].includes(parts[0]) ? parts[0] : 'en';
  const slug = (parts[2] || '').replace(/\/$/, '');
  const R = window.kiraR;
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const cname = (name) => (R && R.country ? R.country(name) : name);
  const NUM_LOCALE = { en: 'en-US', ja: 'ja-JP', ko: 'ko-KR', zh: 'zh-CN' }[locale];

  const T = {
    en: {
      title: 'Market data', h1: (c) => `${c}: market data`, all: 'All markets', latest: 'Latest', history: 'Last six years',
      growthChart: 'Real GDP growth', growthUnit: '% per year', indicator: 'Indicator', updated: (d) => `Data refreshed ${d}.`,
      reports: (c) => `KIRA reports on ${c}`, notFound: 'Market not found', loadFail: 'Could not load the data. Please retry in a moment.',
      none: (c) => `Data for ${c} comes from its national statistics office and is being added.`,
      indexH1: 'Market data for 15 Asia-Pacific markets', indexLead: 'Headline economic indicators for every market KIRA covers, refreshed every week from public sources.',
      lead: (c, v) => `${c}'s real GDP ${v.neg ? 'shrank' : 'grew'} <b>${v.growthAbs}</b> in ${v.year}` + (v.gdp ? `, with GDP at <b>${v.gdp}</b>.` : '.') +
        (v.hh ? ` Households spent <b>${v.hh}</b>` + (v.fdi ? `, and foreign direct investment brought a net <b>${v.fdi}</b>.` : '.') : ''),
      ofYear: (y) => `${y}`
    },
    ja: {
      title: '市場データ', h1: (c) => `${c}：市場データ`, all: '全市場', latest: '最新', history: '直近6年',
      growthChart: '実質GDP成長率', growthUnit: '％（前年比）', indicator: '指標', updated: (d) => `データ更新日：${d}`,
      reports: (c) => `${c}に関するKIRAレポート`, notFound: '市場が見つかりません', loadFail: 'データを読み込めませんでした。しばらくしてから再度お試しください。',
      none: (c) => `${c}のデータは同国の統計機関から追加中です。`,
      indexH1: 'アジア太平洋15市場の市場データ', indexLead: 'KIRAが対象とする全市場の主要経済指標。公開データから毎週更新しています。',
      lead: (c, v) => (v.growth ? `${c}の${v.year}年の実質GDP成長率は<b>${v.growth}</b>` : '') + (v.gdp ? `、名目GDPは<b>${v.gdp}</b>でした。` : '。') +
        (v.hh ? `家計消費支出は<b>${v.hh}</b>` + (v.fdi ? `、対内直接投資の純流入は<b>${v.fdi}</b>です。` : 'です。') : ''),
      ofYear: (y) => `${y}年`
    },
    ko: {
      title: '시장 데이터', h1: (c) => `${c}: 시장 데이터`, all: '전체 시장', latest: '최신', history: '최근 6년',
      growthChart: '실질 GDP 성장률', growthUnit: '% (전년 대비)', indicator: '지표', updated: (d) => `데이터 갱신일: ${d}`,
      reports: (c) => `${c} 관련 KIRA 보고서`, notFound: '시장을 찾을 수 없습니다', loadFail: '데이터를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.',
      none: (c) => `${c} 데이터는 해당국 통계청 자료로 추가하는 중입니다.`,
      indexH1: '아시아·태평양 15개 시장 데이터', indexLead: 'KIRA가 다루는 모든 시장의 주요 경제지표. 공개 자료로 매주 갱신합니다.',
      lead: (c, v) => (v.growth ? `${c}의 ${v.year}년 실질 GDP 성장률은 <b>${v.growth}</b>` : '') + (v.gdp ? `, 명목 GDP는 <b>${v.gdp}</b>입니다.` : '입니다.') +
        (v.hh ? ` 가계 소비지출은 <b>${v.hh}</b>` + (v.fdi ? `, 외국인직접투자 순유입은 <b>${v.fdi}</b>입니다.` : '입니다.') : ''),
      ofYear: (y) => `${y}년`
    },
    zh: {
      title: '市场数据', h1: (c) => `${c}：市场数据`, all: '全部市场', latest: '最新', history: '近六年',
      growthChart: '实际GDP增长率', growthUnit: '%（同比）', indicator: '指标', updated: (d) => `数据更新于${d}。`,
      reports: (c) => `KIRA关于${c}的报告`, notFound: '未找到该市场', loadFail: '无法加载数据，请稍后重试。',
      none: (c) => `${c}的数据来自其国家统计机构，正在添加中。`,
      indexH1: '亚太15个市场的市场数据', indexLead: 'KIRA覆盖的每个市场的主要经济指标，每周根据公开数据更新。',
      lead: (c, v) => (v.growth ? `${c}${v.year}年实际GDP增长<b>${v.growth}</b>` : '') + (v.gdp ? `，国内生产总值为<b>${v.gdp}</b>。` : '。') +
        (v.hh ? `家庭消费支出为<b>${v.hh}</b>` + (v.fdi ? `，外国直接投资净流入<b>${v.fdi}</b>。` : '。') : ''),
      ofYear: (y) => `${y}年`
    }
  }[locale];

  // Formatting: money as US$ with compact notation in the reader's language; percentages to one decimal.
  const compact = new Intl.NumberFormat(NUM_LOCALE, { notation: 'compact', maximumSignificantDigits: 4 });
  const plain = new Intl.NumberFormat(NUM_LOCALE, { maximumFractionDigits: 0 });
  const dec = (d) => new Intl.NumberFormat(NUM_LOCALE, { minimumFractionDigits: d, maximumFractionDigits: d });
  function fmt(v, unit) {
    if (v === null || v === undefined || !Number.isFinite(v)) return '–';
    if (unit === 'usd') return 'US$' + compact.format(v);
    if (unit === 'usd_per_person') return 'US$' + plain.format(v);
    if (unit === 'people') return compact.format(v);
    if (unit === 'pct') return dec(1).format(v) + '%';
    if (unit === 'lcu_per_usd') return Math.abs(v) >= 100 ? plain.format(v) : dec(2).format(v);
    return String(v);
  }
  const label = (ind) => (ind.label && (ind.label[locale] || ind.label.en)) || ind.key;
  const dateFmt = (iso) => (R && R.date ? R.date(iso, 'long') : new Date(iso).toDateString());

  function fail(msg) {
    root.innerHTML = '<div class="r-empty" style="margin-block:64px"><h3>' + esc(msg) + '</h3><a class="r-btn r-btn-outline" href="/' + locale + '/data/">' + esc(T.all) + '</a></div>';
  }
  function sources(list, updated) {
    return '<div class="ed-sources">' + list.map((s) => '<span>' + (s.url ? '<a href="' + esc(s.url) + '" target="_blank" rel="noopener">' + esc(s.attribution) + '</a>' : esc(s.attribution)) + '</span>').join('') +
      (updated ? '<span>' + esc(T.updated(dateFmt(updated))) + '</span>' : '') + '</div>';
  }

  // ---- index page -------------------------------------------------------------------------
  if (!slug) {
    document.title = T.indexH1 + ' — KIRA Research';
    let data;
    try {
      const r = await fetch('/api/econ');
      if (!r.ok) throw new Error(r.status);
      data = await r.json();
    } catch (_e) { return fail(T.loadFail); }
    const units = Object.fromEntries((data.indicators || []).map((i) => [i.key, i]));
    const row = (c, k) => (c.latest[k] && units[k] ? '<dt>' + esc(label(units[k])) + ' ' + esc(T.ofYear(c.latest[k].period)) + '</dt><dd>' + esc(fmt(c.latest[k].value, units[k].unit)) + '</dd>' : '');
    root.innerHTML = '<div class="ed-main"><div class="ed-head"><h1>' + esc(T.indexH1) + '</h1><p class="ed-lead">' + esc(T.indexLead) + '</p></div>' +
      '<div class="ed-grid">' + data.countries.map((c) =>
        '<a class="ed-card" href="/' + locale + '/data/' + esc(c.slug) + '"><h3>' + esc(cname(c.name)) + '</h3>' +
        (Object.keys(c.latest).length ? '<dl>' + ['gdp_usd', 'gdp_growth', 'population'].map((k) => row(c, k)).join('') + '</dl>' : '<span class="ed-note">' + esc(T.none(cname(c.name))) + '</span>') +
        '</a>').join('') + '</div>' + sources(data.sources || []) + '</div>';
    return;
  }

  // ---- country page -----------------------------------------------------------------------
  if (!/^[a-z0-9-]{2,40}$/.test(slug)) return fail(T.notFound);
  let data;
  try {
    const r = await fetch('/api/econ?country=' + encodeURIComponent(slug));
    if (r.status === 404) return fail(T.notFound);
    if (!r.ok) throw new Error(r.status);
    data = await r.json();
  } catch (_e) { return fail(T.loadFail); }

  const C = cname(data.country.name);
  document.title = T.h1(C) + ' — KIRA Research';
  const crumbData = document.getElementById('ed-crumb-data');
  if (crumbData) crumbData.href = '/' + locale + '/data/';
  const crumb = document.getElementById('ed-crumb-country');
  if (crumb) crumb.textContent = C;
  const byKey = Object.fromEntries(data.indicators.map((i) => [i.key, i]));
  const actual = (k) => ((byKey[k] && byKey[k].series) || []).filter((p) => !p[2]);
  const last = (k) => { const s = actual(k); return s.length ? s[s.length - 1] : null; };
  const at = (k, y) => { const p = actual(k).find((x) => x[0] === y); return p ? p[1] : null; };
  const libLink = '<a class="r-btn r-btn-outline" href="/' + locale + '/library?country=' + encodeURIComponent(data.country.name.toLowerCase()) + '">' + esc(T.reports(C)) + '</a>';

  if (!data.indicators.length) {
    root.innerHTML = '<div class="ed-main"><div class="ed-head"><h1>' + esc(T.h1(C)) + '</h1><p class="ed-lead">' + esc(T.none(C)) + '</p></div><div class="ed-links">' + libLink + '</div></div>';
    return;
  }

  // Lead sentence: values of the latest year that has GDP growth.
  const g = last('gdp_growth');
  const year = g ? g[0] : null;
  const v = year ? {
    year,
    growth: fmt(g[1], 'pct'),
    growthAbs: fmt(Math.abs(g[1]), 'pct'),
    neg: g[1] < 0,
    gdp: at('gdp_usd', year) !== null ? fmt(at('gdp_usd', year), 'usd') : '',
    hh: at('household_spend', year) !== null ? fmt(at('household_spend', year), 'usd') : '',
    fdi: at('fdi_inflow', year) !== null ? fmt(at('fdi_inflow', year), 'usd') : ''
  } : null;

  const TILE_KEYS = ['gdp_usd', 'gdp_growth', 'gdp_per_capita', 'household_spend', 'inflation', 'population', 'fdi_inflow', 'urban_share'];
  const tiles = TILE_KEYS.filter((k) => last(k)).map((k) => {
    const p = last(k);
    return '<div class="ed-tile"><span class="lbl">' + esc(label(byKey[k])) + '</span><span class="val">' + esc(fmt(p[1], byKey[k].unit)) + '</span>' +
      '<span class="sub">' + esc(T.ofYear(p[0])) + '</span><svg data-spark="' + k + '" aria-hidden="true"></svg></div>';
  }).join('');

  // Table: every indicator, the last six years that have any value.
  const years = [...new Set(data.indicators.flatMap((i) => actual(i.key).map((p) => p[0])))].sort().slice(-6);
  const table = '<div class="ed-table-wrap"><table class="ed-table"><thead><tr><th>' + esc(T.indicator) + '</th>' + years.map((y) => '<th>' + esc(y) + '</th>').join('') + '</tr></thead><tbody>' +
    data.indicators.map((i) => '<tr><td>' + esc(label(i)) + '</td>' + years.map((y) => '<td>' + esc(fmt(at(i.key, y), i.unit)) + '</td>').join('') + '</tr>').join('') + '</tbody></table></div>';

  root.innerHTML = '<div class="ed-main">' +
    '<div class="ed-head"><h1>' + esc(T.h1(C)) + '</h1>' + (v ? '<p class="ed-lead">' + T.lead(esc(C), Object.fromEntries(Object.entries(v).map(([k, x]) => [k, typeof x === 'string' ? esc(x) : x]))) + '</p>' : '') + '</div>' +
    '<section class="ed-section"><h2>' + esc(T.latest) + '</h2><div class="ed-tiles">' + tiles + '</div></section>' +
    (actual('gdp_growth').length ? '<section class="ed-section"><h2>' + esc(T.growthChart) + '<small>' + esc(T.growthUnit) + '</small></h2><svg class="ed-chart" id="ed-growth" viewBox="0 0 760 240" role="img" aria-label="' + esc(T.growthChart) + '"></svg></section>' : '') +
    '<section class="ed-section"><h2>' + esc(T.history) + '</h2>' + table + '</section>' +
    '<section class="ed-section">' + sources(data.sources, data.updated_at) + '<div class="ed-links">' + libLink + '<a class="r-btn r-btn-outline" href="/' + locale + '/data/">' + esc(T.all) + '</a></div></section>' +
    '</div>';

  // ---- charts -----------------------------------------------------------------------------
  const NS = 'http://www.w3.org/2000/svg';
  const el = (n, a, p) => { const e = document.createElementNS(NS, n); for (const k in a) e.setAttribute(k, a[k]); if (p) p.appendChild(e); return e; };
  const tip = document.body.appendChild(Object.assign(document.createElement('div'), { id: 'ed-tip' }));
  const hover = (node, text) => {
    node.addEventListener('pointermove', (e) => { tip.textContent = text; tip.style.opacity = 1; tip.style.left = Math.min(e.clientX + 12, innerWidth - tip.offsetWidth - 8) + 'px'; tip.style.top = Math.max(8, e.clientY - 32) + 'px'; });
    node.addEventListener('pointerleave', () => { tip.style.opacity = 0; });
  };

  document.querySelectorAll('[data-spark]').forEach((svg) => {
    const vals = actual(svg.dataset.spark).slice(-11).map((p) => p[1]);
    if (vals.length < 2) return;
    const W = 120, H = 30, mn = Math.min(...vals), mx = Math.max(...vals);
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.setAttribute('preserveAspectRatio', 'none');
    const px = (i) => 2 + i * (W - 4) / (vals.length - 1), py = (x) => H - 3 - (H - 6) * (x - mn) / ((mx - mn) || 1);
    const pts = vals.map((x, i) => `${px(i)},${py(x)}`).join(' ');
    el('polygon', { points: `${px(0)},${H} ${pts} ${px(vals.length - 1)},${H}`, fill: 'rgba(26,102,240,.12)' }, svg);
    el('polyline', { points: pts, fill: 'none', stroke: 'var(--primary)', 'stroke-width': 1.6, 'vector-effect': 'non-scaling-stroke' }, svg);
  });

  const gsvg = document.getElementById('ed-growth');
  if (gsvg) {
    // Phones get a narrower drawing with fewer years so the labels stay readable.
    const narrow = gsvg.getBoundingClientRect().width < 560;
    const rows = actual('gdp_growth').slice(narrow ? -10 : -16);
    const W = narrow ? 400 : 760, H = narrow ? 220 : 240, L = 34, Rr = 8, Tt = 12, B = 28;
    gsvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    const lo = Math.min(0, ...rows.map((r) => r[1])), hi = Math.max(0, ...rows.map((r) => r[1]));
    const top = Math.ceil(hi / 2) * 2 || 2, bot = Math.floor(lo / 2) * 2;
    const y = (x) => Tt + (H - Tt - B) * (top - x) / (top - bot);
    for (let t = bot; t <= top; t += 2) {
      el('line', { x1: L, x2: W - Rr, y1: y(t), y2: y(t), class: t === 0 ? 'base' : 'grid' }, gsvg);
      el('text', { x: L - 6, y: y(t) + 4, 'text-anchor': 'end' }, gsvg).textContent = t;
    }
    const step = (W - L - Rr) / rows.length, bw = Math.min(28, step * 0.62);
    rows.forEach(([yr, val], i) => {
      const cx = L + step * i + step / 2, y0 = y(0), y1 = y(val), h = Math.abs(y1 - y0), r = Math.min(3, h);
      const x = cx - bw / 2, up = val >= 0, edge = y1;
      const d = up
        ? `M${x},${y0}V${edge + r}Q${x},${edge} ${x + r},${edge}H${x + bw - r}Q${x + bw},${edge} ${x + bw},${edge + r}V${y0}Z`
        : `M${x},${y0}V${edge - r}Q${x},${edge} ${x + r},${edge}H${x + bw - r}Q${x + bw},${edge} ${x + bw},${edge - r}V${y0}Z`;
      el('path', { d, class: 'bar' + (up ? '' : ' neg') }, gsvg);
      hover(el('rect', { x: cx - step / 2, y: Tt, width: step, height: H - Tt - B, fill: 'transparent' }, gsvg), `${yr}: ${fmt(val, 'pct')}`);
      if (i % 2 === (rows.length - 1) % 2) el('text', { x: cx, y: H - 8, 'text-anchor': 'middle' }, gsvg).textContent = yr;
    });
  }
})();
